import{_ as d,C as i,o as s,c,a2 as r,j as t,a,E as n}from"./chunks/framework.Di-jvWLj.js";const y=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1793384109000}'),l={name:"roadmap.md"},h={id:"m1-issue-triage-end-to-end",tabindex:"-1"},p={id:"m2-mail-digest",tabindex:"-1"},m={id:"m3-dependency-upgrade",tabindex:"-1"};function u(g,e,b,f,v,k){const o=i("Badge");return s(),c("div",null,[e[9]||(e[9]=r('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>chamvi is built milestone by milestone, each defined by one real agent that has to work end to end. The framework foundations below are implemented on <code>master</code>; the milestone sections separate those foundations from agents and integrations still to build. Merged work may not yet be in the latest published release. There are no delivery dates.</p><p>Last checked against the codebase and GitHub on <strong>2026-10-30</strong>.</p><h2 id="implemented-foundations" tabindex="-1">Implemented foundations <a class="header-anchor" href="#implemented-foundations" aria-label="Permalink to &quot;Implemented foundations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Contents</th></tr></thead><tbody><tr><td><code>@chamvi/core</code></td><td><code>defineAgent()</code> with channel subscriptions, tool hooks and structured instructions; <code>IChannel</code>, <code>consoleChannel()</code>, durable runs, checkpoints, budgets, effect tools, agent state, approvals with choices, same-agent run handoff, opt-in conversation recall and notes, scoped skills, shared agent/subscription execution caps, composable repositories and <code>createMemoryStore()</code></td></tr><tr><td><code>@chamvi/test-kit</code></td><td>Repository, conversation and workspace contract suites, <code>ControllableClock</code>, <code>createGitFixture</code>, <code>createFakeGithub</code>, mock models and skill runtime fixtures</td></tr><tr><td><code>@chamvi/channel-cron</code></td><td>The cron channel <code>cronChannel()</code> and <code>cron.on()</code> (one locked hubwire component per subscription, overlap policies, timezones), <code>runJob()</code> for one-shot jobs</td></tr><tr><td><code>@chamvi/store-db</code></td><td><code>createDatabaseStore()</code> on Postgres, <code>migrateStore</code>, <code>purgeExpired</code>. See <a href="/repositories/typeorm">TypeORM store</a></td></tr><tr><td><code>@chamvi/http</code></td><td>REST control API, server-sent events, <code>http</code>, <code>mcp</code> and <code>webhook</code> channels, the <code>/channels/&lt;name&gt;</code> mount, <code>/healthz</code>, <code>/readyz</code>, <code>/metrics</code>, MCP, static-token, authup and OIDC authentication, configurable channel HTTP limits and graceful shutdown. See <a href="/guide/http">HTTP API &amp; MCP</a></td></tr><tr><td><code>@chamvi/github</code></td><td>GitHub App auth, per-repository installation resolution, signed and deduplicated channel deliveries, <code>github.on()</code> subscriptions, issue, pull-request, checks and release tools, and effect writes with marker reconciliation. See <a href="/deployment/github-app">GitHub App</a></td></tr><tr><td><code>@chamvi/sandbox</code></td><td>Sandbox contracts, path, repository and limit rules, run-scoped recoverable workspaces, bash-first credentials and bounded, path-scoped repository instructions. See <a href="/guide/workspaces">Workspaces &amp; Coding</a></td></tr><tr><td><code>@chamvi/sandbox-local</code>, <code>@chamvi/sandbox-docker</code>, <code>@chamvi/sandbox-k8s</code></td><td>Workspace providers: a temporary directory (development), a container per workspace, a pod per workspace (root inside, strict at the edge, a hardened mode, a shared package cache); the <code>ghcr.io/chamvi/sandbox-dev</code> image with mise for any toolchain</td></tr><tr><td><code>@chamvi/channel-openclaw</code></td><td>The OpenClaw channel: messages and approval requests into an OpenClaw chat through its hooks endpoint, with an <code>Idempotency-Key</code>. See <a href="/deployment/openclaw">OpenClaw</a></td></tr><tr><td><code>@chamvi/coding</code></td><td>Coding tools (<code>read_file</code>, <code>write_file</code>, <code>edit_file</code>, <code>grep</code>, <code>list_files</code>, <code>bash</code>, <code>git_diff</code>) over a run&#39;s workspaces and the <code>ICodingBackend</code> contract</td></tr><tr><td><code>@chamvi/tool-web</code></td><td><code>web_fetch</code> behind an address check, through a hapic client with the proxy from the environment. See <a href="/guide/tools#web-research-tools">Web research tools</a></td></tr><tr><td><code>@chamvi/ui</code></td><td>Vue 3 dashboard served by <code>uiRoutes()</code>: an agents overview, runs started from the agent page, runs with live steps, an approvals inbox, agent state, schedules</td></tr><tr><td><code>@chamvi/app</code>, <code>@chamvi/cli</code></td><td><code>createApp()</code> with orkos modules, folder agents and dependency preparation, named model providers and app-wide defaults, <code>createTestApp()</code>, <code>start --check</code>, visible reload failures, and the <code>chamvi</code> commands <code>dev</code>, <code>build</code>, <code>start</code>, <code>run-job</code>, <code>migrate</code>. See <a href="/guide/app">Apps &amp; Modules</a>, <a href="/guide/agent-folders">Agent Folders</a> and <a href="/reference/cli">CLI</a></td></tr><tr><td><code>@chamvi/skills</code></td><td>Verified, digest-pinned local bundles and Git sources, startup installation, agent-scoped metadata catalogs and the <code>load_skill</code> tool. See <a href="/guide/skills">Approved Skills</a></td></tr></tbody></table><p>The <a href="/deployment/docker">base image</a>, <a href="https://github.com/chamvi/helm" target="_blank" rel="noreferrer">Helm chart</a> and <a href="https://github.com/chamvi/agent-template" target="_blank" rel="noreferrer">agent template</a> also exist. The chart and template support default models and named providers. Their existence does not by itself complete the end-to-end agent milestones.</p><h2 id="recently-completed" tabindex="-1">Recently completed <a class="header-anchor" href="#recently-completed" aria-label="Permalink to &quot;Recently completed&quot;">​</a></h2><ul><li><strong>Sandbox defaults and bash-first credentials:</strong> safer workspace defaults, credential redaction, removal of dedicated credential-mode Git tools, and a pinned GitHub CLI in the development sandbox image (<a href="https://github.com/chamvi/chamvi/pull/60" target="_blank" rel="noreferrer">#60</a>, <a href="https://github.com/chamvi/chamvi/pull/87" target="_blank" rel="noreferrer">#87</a>).</li><li><strong>Maintainer foundations:</strong> GitHub pull-request tools, approvals with choices and same-agent run handoff (<a href="https://github.com/chamvi/chamvi/pull/64" target="_blank" rel="noreferrer">#64</a>, <a href="https://github.com/chamvi/chamvi/pull/65" target="_blank" rel="noreferrer">#65</a>, <a href="https://github.com/chamvi/chamvi/pull/66" target="_blank" rel="noreferrer">#66</a>). Cross-agent delegation remains planned.</li><li><strong>Operational controls:</strong> startup validation, visible agent reload failures, shared agent/subscription execution caps and configurable channel HTTP limits (<a href="https://github.com/chamvi/chamvi/pull/61" target="_blank" rel="noreferrer">#61</a>, <a href="https://github.com/chamvi/chamvi/pull/93" target="_blank" rel="noreferrer">#93</a>).</li><li><strong>Repository context and reusable skills:</strong> scoped repository instructions and verified skill preparation/loading (<a href="https://github.com/chamvi/chamvi/pull/95" target="_blank" rel="noreferrer">#95</a>, <a href="https://github.com/chamvi/chamvi/pull/94" target="_blank" rel="noreferrer">#94</a>).</li><li><strong>Conversation memory:</strong> opt-in, authorized recent-history recall and explicit notes, durable turn ownership and composable persistence repositories (<a href="https://github.com/chamvi/chamvi/pull/96" target="_blank" rel="noreferrer">#96</a>). This does not include a native chat transport or the broader context-management plan.</li></ul><h2 id="milestones" tabindex="-1">Milestones <a class="header-anchor" href="#milestones" aria-label="Permalink to &quot;Milestones&quot;">​</a></h2>',9)),t("h3",h,[e[0]||(e[0]=a("M1: issue triage end to end ",-1)),n(o,{type:"warning",text:"In progress"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#m1-issue-triage-end-to-end","aria-label":'Permalink to "M1: issue triage end to end <Badge type="warning" text="In progress" />"'},"​",-1))]),e[10]||(e[10]=t("p",null,"On every new issue in the owner's repositories, a triage agent labels it, checks for duplicates, tries to reproduce the bug against the latest release in a sandbox and posts a first reply asking for missing details. A periodic sweep catches issues missed while the agent was down.",-1)),e[11]||(e[11]=t("p",null,"The store, cron, HTTP/MCP authentication, GitHub integration, sandboxes, coding tools, OpenClaw, UI, CLI and deployment foundations are implemented. The triage agent itself, its end-to-end deployment acceptance and the own-tools coding backend remain open. M1 is not complete just because its infrastructure exists.",-1)),t("h3",p,[e[3]||(e[3]=a("M2: mail digest ",-1)),n(o,{type:"warning",text:"Planned"}),e[4]||(e[4]=a()),e[5]||(e[5]=t("a",{class:"header-anchor",href:"#m2-mail-digest","aria-label":'Permalink to "M2: mail digest <Badge type="warning" text="Planned" />"'},"​",-1))]),e[12]||(e[12]=t("p",null,"Every morning, and on request through OpenClaw, the owner gets a short digest: what matters today, what still needs action, what is waiting on others. Open loops are tracked in typed state collections across days. The mail (IMAP) channel and digest agent remain planned. Opt-in conversation recall and notes are already implemented, but do not yet deliver this mail workflow or the original threaded-run design.",-1)),t("h3",m,[e[6]||(e[6]=a("M3: dependency upgrade ",-1)),n(o,{type:"warning",text:"Planned"}),e[7]||(e[7]=a()),e[8]||(e[8]=t("a",{class:"header-anchor",href:"#m3-dependency-upgrade","aria-label":'Permalink to "M3: dependency upgrade <Badge type="warning" text="Planned" />"'},"​",-1))]),e[13]||(e[13]=r('<p>When Renovate opens a pull request, an agent reads the changelog of the bumped package, fixes breaking changes in a sandbox, runs the tests and pushes commits. It pings the owner only when it is stuck. M3 adds long coding runs, a Claude Code coding backend and stuck detection.</p><h2 id="planned-packages" tabindex="-1">Planned packages <a class="header-anchor" href="#planned-packages" aria-label="Permalink to &quot;Planned packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Status</th><th>Purpose</th></tr></thead><tbody><tr><td>Coding backend on the own tools</td><td>Planned (M1)</td><td>An <code>ICodingBackend</code> that runs the coding tools in a nested tool loop</td></tr><tr><td><code>@chamvi/coding-claude-code</code></td><td>Planned (M3)</td><td>A coding backend that runs Claude Code inside the sandbox</td></tr><tr><td><code>@chamvi/mail</code></td><td>Planned (M2)</td><td>IMAP channel and tools</td></tr><tr><td><code>@chamvi/chat</code></td><td>Planned; older PR <a href="https://github.com/chamvi/chamvi/pull/32" target="_blank" rel="noreferrer">#32</a> remains open</td><td>Native Chat SDK channels and WhatsApp transport; conversation memory is implemented separately</td></tr></tbody></table><h2 id="remaining-framework-work" tabindex="-1">Remaining framework work <a class="header-anchor" href="#remaining-framework-work" aria-label="Permalink to &quot;Remaining framework work&quot;">​</a></h2><ul><li><strong>Coding and operations:</strong> own-tools coding backend, visual-regression repair on dependency PRs, provider fallback on quota/rate limits and execution-local artifact hydration caching.</li><li><strong>Agent composition:</strong> delegation between different agents, remote agents over A2A, UI overrides and agent uploads. Same-agent handoff is already implemented.</li><li><strong>Context and safety:</strong> compaction, prompt-cache controls, deferred tools, central approval policies, automatic permission classification and untrusted-content isolation. Conversation memory, scoped instructions and skills are foundations, not completion of these plans.</li><li><strong>Observability:</strong> OpenTelemetry tracing and replay-based evals.</li><li><strong>Follow-ups to merged work:</strong> race-free confinement for repository instruction reads (<a href="https://github.com/chamvi/chamvi/issues/92" target="_blank" rel="noreferrer">#92</a>), replacing the temporary skills SDK fork (<a href="https://github.com/chamvi/chamvi/issues/97" target="_blank" rel="noreferrer">#97</a>), and tool-accessible conversation reset/deletion (<a href="https://github.com/chamvi/chamvi/issues/98" target="_blank" rel="noreferrer">#98</a>).</li></ul><p>See <a href="https://github.com/chamvi/chamvi/issues" target="_blank" rel="noreferrer">open issues</a> for current tracking. An open issue may lag a merged implementation; code and merged PRs distinguish delivered scope from remaining follow-ups.</p><p>Two changes happened upstream first: a lock hook, timezone support and the scheduled time per tick shipped in <a href="https://github.com/tada5hi/hubwire" target="_blank" rel="noreferrer">hubwire</a> 0.2.2 (for the cron channel), and a fetch-native token verification in <a href="https://github.com/authup/authup" target="_blank" rel="noreferrer">authup</a> 1.0.0-beta.70 (for the HTTP API).</p><h2 id="stability" tabindex="-1">Stability <a class="header-anchor" href="#stability" aria-label="Permalink to &quot;Stability&quot;">​</a></h2><p>chamvi is pre-1.0 and owner-first. Until M3, minor versions may break the API and the store schema.</p>',9))])}const x=d(l,[["render",u]]);export{y as __pageData,x as default};
